def is_power_of_two(n):
    if n <= 0:
        return False
    return (n & (n - 1)) == 0

solutions = []
max_n = 5  # Search up to n=5
max_x = 20 # Search up to x=20

for n in range(2, max_n + 1):
    for x in range(n + 1, max_x + 1):
        # Calculate R = x^n + x - 2
        R = x**n + x - 2

        if is_power_of_two(R):
            # R = 2^k, so k = log2(R)
            k = R.bit_length() - 1
            solutions.append((x, n, k, R))

print(f"Solutions found (x, n, k, 2^k): {solutions}")
